import { IPlugin } from '@shell/core/types';

export const NAME = 'multisite-cluster-provisioner';

// Produkt BEDINGUNGSLOS registrieren (wie cloud-services-marketplace). KEIN Gate auf die
// Nav-Registrierung: init() läuft einmalig beim Plugin-Load, bevor management-Schemas da
// sind → ein Admin-Check hier bleibt fail-closed und das Produkt wäre für ALLE (auch
// Admins) unsichtbar. Admin-only ist auf die Wizard-Aktion gezogen (lib/gate.ts isAllowed
// → isAdminUser, zur Nav-Zeit korrekt ausgewertet).
export function init($plugin: IPlugin, store: any) {
  const { product } = $plugin.DSL(store, NAME);

  product({
    inStore:             'management',
    icon:                'globe',
    label:               'Multi-Site Cluster Provisioner',
    removable:           false,
    showClusterSwitcher: false,
    category:            'global',
    to:                  { name: NAME },
  } as any);
}
